package com.gameaggregator.webhookservice.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="webhook_deliveries",uniqueConstraints=@UniqueConstraint(columnNames={"endpointId","eventId"})) public class WebhookDelivery{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID endpointId;@Column(nullable=false)public String eventId;@Column(nullable=false)public String eventType;@Lob @Column(nullable=false)public String payload;@Column(nullable=false)public String status="PENDING";@Column(nullable=false)public int attemptCount;@Column(nullable=false)public Instant nextAttemptAt=Instant.now();public Integer lastHttpStatus;public String lastError;@Column(nullable=false)public Instant createdAt=Instant.now();public Instant deliveredAt;@Version public long revision;protected WebhookDelivery(){}public WebhookDelivery(UUID e,String i,String t,String p){endpointId=e;eventId=i;eventType=t;payload=p;}}